const b = $json.body || $json;
const jobId = String(b.jobId || '').trim();
const slug = String(b.slug || b.cliente || '').trim();
const landingUrl = String(b.landingUrl || b.url || '').trim();
const host = String(b.host || 'vercel').trim();
if (!landingUrl || !/^https?:\/\//i.test(landingUrl)) {
  return [{ json: { ok: false, error: 'landingUrl inválida' } }];
}
return [{ json: {
  ok: true,
  sistema: '07-presencia-digital',
  etapa: 'deploy',
  jobId,
  slug,
  landingUrl,
  host,
  status: 'web_publicada',
  siguiente: 'gbp_checklist',
  todo: 'TODO: guardar URL en clientes/{slug}/entregables/',
  at: new Date().toISOString()
}}];
